      { id: "st-22", zh: "冬至", pinyin: "Dōngzhì", hanViet: "Đông Chí", nameVi: "Đông Chí", nameEn: "Winter Solstice", solarLongitudeDeg: 270, gregorianApproxDate: "21/12", threePhenologiesVi: ["Giun đất cuộn mình sâu trong lòng đất", "Hươu sừng lớn rụng gạc", "Mạch nước suối ngầm bắt đầu ấm động"], threePhenologiesEn: ["Earthworms curl deep underground", "Moose shed antlers", "Underground springs begin to stir"], seasonalTeaFoodVi: "Miền Bắc ăn sủi cảo, miền Nam ăn chè trôi nước (Thang Viên) đoàn viên.", seasonalTeaFoodEn: "Dumplings in the North; sweet glutinous rice balls (Tangyuan) in the South.", eastAsianPoemZh: "天时人事日相催，冬至阳生春又来。", poemVi: "Thời trời việc người nối nhau giục, Đông Chí dương sinh xuân sắp về." },
      { id: "st-23", zh: "小寒", pinyin: "Xiǎohán", hanViet: "Tiểu Hàn", nameVi: "Tiểu Hàn", nameEn: "Minor Cold", solarLongitudeDeg: 285, gregorianApproxDate: "05/01", threePhenologiesVi: ["Chim nhạn bắt đầu hướng về phương Bắc", "Chim ác là bắt đầu làm tổ mới", "Chim trĩ rừng cất tiếng gáy"], threePhenologiesEn: ["Wild geese turn northward", "Magpies start building nests", "Pheasants call in the hills"], seasonalTeaFoodVi: "Cháo Lạp Bát tám loại ngũ cốc & cơm nếp lạp vị Quảng Đông.", seasonalTeaFoodEn: "Laba Eight-Treasure porridge and Cantonese cured-meat sticky rice.", eastAsianPoemZh: "小寒连大吕，欢鹊垒新巢。", poemVi: "Tiểu Hàn nối nhịp nhạc xưa, chim khách vui mừng xây tổ mới." },
      { id: "st-24", zh: "大寒", pinyin: "Dàhán", hanViet: "Đại Hàn", nameVi: "Đại Hàn", nameEn: "Major Cold", solarLongitudeDeg: 300, gregorianApproxDate: "20/01", threePhenologiesVi: ["Gà bắt đầu ấp trứng đón xuân", "Chim ưng săn mồi mạnh mẽ giữa rét đậm", "Sông hồ đóng băng dày cứng nhất năm"], threePhenologiesEn: ["Hens begin brooding", "Birds of prey hunt swiftly", "Rivers freeze to maximum depth"], seasonalTeaFoodVi: "Bánh gạo Niên Cao, canh gà nấm hương & trà gừng táo đỏ đón Tết.", seasonalTeaFoodEn: "New Year rice cakes (Niangao), mushroom chicken broth, and ginger-date tea.", eastAsianPoemZh: "旧雪未及消，新雪又拥户。", poemVi: "Tuyết cũ chưa kịp tan, tuyết mới đã chất đầy ngoài cửa." }
